// ── Storage ───────────────────────────────────────────
function storageGet(key, cb) {
  try {
    chrome.storage.local.get([key], function(r) {
      if (chrome.runtime.lastError) { cb(null); return; }
      cb(r[key] || null);
    });
  } catch(e) { cb(null); }
}
function storageSet(key, val, cb) {
  try {
    var obj = {}; obj[key] = val;
    chrome.storage.local.set(obj, function() {
      if (chrome.runtime.lastError) console.error('storage error:', chrome.runtime.lastError);
      if (cb) cb();
    });
  } catch(e) { if (cb) cb(); }
}

// ── 설정 ─────────────────────────────────────────────
function loadSettings() {
  storageGet('cfg', function(saved) {
    if (saved) {
      CFG = Object.assign(CFG, saved);
      document.getElementById('cfg-apikey').value = CFG.apiKey || '';
      document.getElementById('cfg-server').value = CFG.server || '';
      document.getElementById('cfg-uid').value = CFG.uid || '';
      document.getElementById('cfg-upw').value = CFG.upw || '';
      document.getElementById('cfg-gsurl').value = CFG.gsUrl || '';
      document.getElementById('cfg-kakao-sig').value = CFG.kakaoSig || '';
      document.getElementById('cfg-openai-key').value = CFG.openAiKey || '';
      document.getElementById('cfg-gemini-key').value = CFG.geminiKey || '';
      document.getElementById('cfg-whisper-hint').value = CFG.whisperHint || '';
    }
    updateTopStatus();
  });
}
function saveSettings() {
  CFG.apiKey = document.getElementById('cfg-apikey').value.trim();
  CFG.server = (document.getElementById('cfg-server').value.trim() || '192.168.0.223:6982').replace(/\/+$/, '');
  CFG.uid = document.getElementById('cfg-uid').value.trim();
  CFG.upw = document.getElementById('cfg-upw').value.trim();
  CFG.gsUrl = document.getElementById('cfg-gsurl').value.trim();
  CFG.kakaoSig = document.getElementById('cfg-kakao-sig').value.trim();
  CFG.openAiKey = document.getElementById('cfg-openai-key').value.trim();
  CFG.geminiKey = document.getElementById('cfg-gemini-key').value.trim();
  CFG.whisperHint = document.getElementById('cfg-whisper-hint').value.trim();
  if (!CFG.apiKey) { showStatus('Claude API 키를 입력해주세요.', 'err'); return; }
  storageSet('cfg', CFG, function() {
    storageGet('cfg', function(saved) {
      if (saved && saved.apiKey) {
        showStatus('✅ 설정이 저장되었습니다!', 'ok');
        updateTopStatus();
        toggleSettings();
      } else {
        showStatus('⚠️ 저장 실패 - 다시 시도해주세요.', 'err');
      }
    });
  });
}
function toggleSettings() {
  document.getElementById('settings-panel').classList.toggle('open');
}
function updateTopStatus() {
  var parts = [];
  if (CFG.apiKey) parts.push('Claude ✓');
  if (CFG.openAiKey) parts.push('Whisper ✓');
  if (CFG.geminiKey) parts.push('Gemini ✓');
  if (CFG.uid) parts.push('한의맥 ✓');
  if (CFG.gsUrl) parts.push('구글시트 ✓');
  document.getElementById('top-status').textContent = parts.join(' | ');
  updateRecModeBadge();
}
function updateRecModeBadge() {
  var icon = document.getElementById('rec-mode-icon');
  var text = document.getElementById('rec-mode-text');
  var badge = document.getElementById('rec-mode-badge');
  if (!icon || !text || !badge) return;
  if (CFG.openAiKey) {
    icon.textContent = '✦'; text.textContent = 'Whisper AI 모드';
    badge.style.background = 'var(--blue-bg)'; badge.style.color = 'var(--blue)'; badge.style.borderColor = '#b0c8f0';
  } else {
    icon.textContent = '●'; text.textContent = '기본 음성인식 모드';
    badge.style.background = 'var(--surface2)'; badge.style.color = 'var(--text3)'; badge.style.borderColor = 'var(--border2)';
  }
}

// ── 상태 메시지 ───────────────────────────────────────
function showStatus(msg, type) {
  var el = document.getElementById('status-bar');
  el.style.display = '';
  el.textContent = msg;
  el.className = 'status-bar show ' + (type || 'info');
  clearTimeout(window._statusTimer);
  if (type === 'ok') window._statusTimer = setTimeout(function(){ el.style.display='none'; }, 5000);
}

// ── 탭 전환 (자유 이동) ───────────────────────────────
function switchTab(n) {
  for (var i = 1; i <= 6; i++) {
    var panel = document.getElementById('panel' + i);
    var tab = document.getElementById('tab' + i);
    if (panel) panel.style.display = (i === n) ? '' : 'none';
    if (tab) {
      tab.className = 'tab' + (i === n ? ' active' : '');
    }
  }
  window.scrollTo(0, 0);
  // 탭 진입 처리
  if (n === 5) initSmsTab();
  if (n === 3) syncInlineInput();
  if (n === 6) loadHerbPatients();
}

// ── 유틸 ─────────────────────────────────────────────
function base() { return 'http://' + CFG.server + '/api'; }
function getAuth() { return 'userID=' + encodeURIComponent(CFG.uid) + '&userPWD=' + encodeURIComponent(CFG.upw); }
function authUrl(url) { return url + (url.indexOf('?') !== -1 ? '&' : '?') + getAuth(); }
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function getName(p) { return p.수진자명||p.이름||p.성명||p.환자명||p.챠트번호||''; }
function getBirth(p) { return p.생일||p.생년월일||''; }
function getPhone(p) { return p.이동전화||p.전화번호||p.연락번호||p.핸드폰||''; }

// ── 탭1: 오늘 환자 대시보드 ─────────────────────────────
var _todayPatients = [];

function loadTodayPatients() {
  var el = document.getElementById('today-list');
  el.innerHTML = '<div class="dashboard-loading">불러오는 중...</div>';
  document.getElementById('dashboard-count').textContent = '';
  var today = new Date().toISOString().split('T')[0];
  chrome.runtime.sendMessage({
    type: 'HANYMAC_API',
    url: authUrl(base() + '/patinfo/waitpat?date=' + today),
    options: { credentials: 'omit' }
  }, function(response) {
    var data = (response && response.success && response.data && response.data.data) ? response.data.data : null;
    if (!data) {
      el.innerHTML = '<div class="dashboard-empty">환자 정보를 불러올 수 없습니다</div>';
      return;
    }
    // 대기(1) 먼저, 그 안에서 접수시간 순
    data.sort(function(a, b) {
      if (a.진료상태 === 1 && b.진료상태 !== 1) return -1;
      if (a.진료상태 !== 1 && b.진료상태 === 1) return 1;
      return (a.접수시간||'').localeCompare(b.접수시간||'');
    });
    _todayPatients = data;
    renderTodayPatients();
  });
}

function renderTodayPatients() {
  var data = _todayPatients;
  var el = document.getElementById('today-list');
  if (!data.length) {
    el.innerHTML = '<div class="dashboard-empty">오늘 접수된 환자가 없습니다</div>';
    document.getElementById('dashboard-count').textContent = '';
    return;
  }
  var waitCount = data.filter(function(r){ return r.진료상태 === 1; }).length;
  var total = data.length;
  document.getElementById('dashboard-count').textContent = '대기 ' + waitCount + ' / 전체 ' + total;

  var currentChartNo = state.patient ? state.patient.챠트번호 : null;
  el.innerHTML = data.map(function(r, i) {
    var isWait = r.진료상태 === 1;
    var statusClass = isWait ? 'status-wait' : 'status-done';
    var badgeClass = isWait ? 'wait' : 'done';
    var badgeText = isWait ? '대기' : '완료';
    var timeStr = (r.접수시간||'').slice(0,5);
    var isActive = currentChartNo && r.챠트번호 === currentChartNo ? ' active' : '';
    return '<div class="today-item ' + statusClass + isActive + '" data-today-idx="' + i + '">' +
      '<span class="today-seq">' + (i+1) + '</span>' +
      '<span class="today-name">' + esc(r.수진자명||'-') + '</span>' +
      '<span class="today-time">' + esc(timeStr) + '</span>' +
      '<span class="today-badge ' + badgeClass + '">' + badgeText + '</span>' +
    '</div>';
  }).join('');

  el.querySelectorAll('.today-item').forEach(function(item) {
    item.addEventListener('click', function() {
      var idx = parseInt(this.dataset.todayIdx);
      var p = _todayPatients[idx];
      // 대시보드 active 표시
      el.querySelectorAll('.today-item').forEach(function(x){ x.classList.remove('active'); });
      this.classList.add('active');
      selectPatient(p);
    });
  });
}

// ── 탭1: 환자 검색 ───────────────────────────────────
function searchPatient() {
  var q = document.getElementById('search-input').value.trim();
  if (!q) return;
  if (!CFG.uid) { showStatus('설정에서 한의맥 아이디/비밀번호를 입력해주세요.', 'err'); return; }
  var rl = document.getElementById('result-list');
  rl.style.display = 'block';
  rl.innerHTML = '<div style="padding:10px;color:var(--text3);text-align:center">검색 중...</div>';
  // SW가 sleep 상태일 경우 ping으로 깨운 뒤 100ms 후 실제 요청
  chrome.runtime.sendMessage({ type: 'STORAGE_GET', key: '__ping' }, function() {
    setTimeout(function() { doSearchPatient(q, rl); }, 100);
  });
}

function doSearchPatient(q, rl) {
  chrome.runtime.sendMessage({
    type: 'HANYMAC_API',
    url: authUrl(base() + '/patinfo/search?searchStr=' + encodeURIComponent(q)),
    options: { credentials:'omit' }
  }, function(response) {
    if (!response || !response.success) {
      rl.innerHTML = '<div style="padding:10px;color:var(--red)">⚠️ ' + (response ? response.error : '연결 실패') + '</div>';
      return;
    }
    var json = response.data;
    if (json.__html) { rl.innerHTML = '<div style="padding:10px;color:var(--red)">⚠️ 한의맥에 먼저 로그인해주세요.</div>'; return; }
    if (!json.data || json.data.length === 0) { rl.innerHTML = '<div style="padding:10px;color:var(--text3);text-align:center">검색 결과가 없습니다.</div>'; return; }
    window._searchData = json.data;
    rl.innerHTML = json.data.map(function(p, i) {
      return '<div class="result-item" data-idx="' + i + '">' +
        '<div class="result-name">' + esc(getName(p)) + '</div>' +
        '<div class="result-sub">차트번호: ' + esc(p.챠트번호||'-') +
        (getBirth(p) ? ' | ' + esc(getBirth(p)) : '') +
        (getPhone(p) ? ' | ☎ ' + esc(getPhone(p)) : '') + '</div></div>';
    }).join('');
    rl.querySelectorAll('.result-item').forEach(function(el) {
      el.addEventListener('click', function(){ selectPatient(parseInt(this.dataset.idx)); });
    });
  });
}

function selectPatient(idx) {
  var p = (typeof idx === 'object') ? idx : window._searchData[idx];
  document.getElementById('result-list').style.display = 'none';
  showStatus('진료 기록을 불러오는 중...', 'info');
  chrome.runtime.sendMessage({
    type: 'HANYMAC_API',
    url: authUrl(base() + '/treat/treatrecord?ChartNumber=' + encodeURIComponent(p.챠트번호) + '&page=1&visit=false'),
    options: { credentials:'omit' }
  }, function(response) {
    var json = (response && response.success) ? response.data : {};
    state.visitList = (json.data && json.data.length > 0) ? json.data : [];
    state.patient = p;
    document.getElementById('pt-name').textContent = getName(p);
    document.getElementById('pt-info').textContent = '차트번호: ' + (p.챠트번호||'-') + (getBirth(p)?' | '+getBirth(p):'') + (getPhone(p)?' | ☎ '+getPhone(p):'');
    document.getElementById('selected-patient').style.display = 'flex';
    document.getElementById('btn-next1').disabled = false;
    document.getElementById('status-bar').style.display = 'none';
    var sel = document.getElementById('visit-select');
    sel.innerHTML = '';
    if (state.visitList.length > 0) {
      state.visitList.forEach(function(v, i) {
        var opt = document.createElement('option');
        opt.value = i;
        opt.textContent = (v.진료일자||v.일자||'날짜미상') + (i===0?' (최근)':'');
        sel.appendChild(opt);
      });
      document.getElementById('visit-row').style.display = 'flex';
    } else {
      document.getElementById('visit-row').style.display = 'none';
    }
    // 탭 이름에 환자명 반영
    document.getElementById('tab1').querySelector('.tab-txt').textContent = getName(p);
    document.getElementById('tab1').classList.add('done');
    // 진료 기록 있으면 차트 불러오기 버튼 표시
    if (state.visitList.length > 0) {
      document.getElementById('load-chart-row').style.display = '';
      updateLoadChartPreview();
    }
  });
}

function clearPatient() {
  state.patient = null; state.visitList = [];
  document.getElementById('selected-patient').style.display = 'none';
  document.getElementById('visit-row').style.display = 'none';
  document.getElementById('load-chart-row').style.display = 'none';
  document.getElementById('load-chart-preview').style.display = 'none';
  document.getElementById('search-input').value = '';
  document.querySelectorAll('.today-item').forEach(function(x){ x.classList.remove('active'); });
  document.getElementById('btn-next1').disabled = true;
  document.getElementById('tab1').querySelector('.tab-txt').textContent = '환자선택';
  document.getElementById('tab1').classList.remove('done');
}

