// 진료일 변경 시 미리보기 업데이트
function onVisitSelectChange() {
  updateLoadChartPreview();
}

// 선택된 진료일의 차트 내용 미리보기
function updateLoadChartPreview() {
  var sel = document.getElementById('visit-select');
  var preview = document.getElementById('load-chart-preview');
  if (!sel || !preview) return;
  var idx = parseInt(sel.value) || 0;
  var v = state.visitList[idx];
  if (!v) return;
  var memo = v.증상 || v.내용 || v.차트내용 || v.메모 || '';
  if (memo) {
    preview.textContent = memo.slice(0, 300) + (memo.length > 300 ? '...' : '');
    preview.style.display = '';
  } else {
    preview.textContent = '(저장된 차트 내용 없음)';
    preview.style.display = '';
  }
}

// SOAP 텍스트 파싱: [S]/[O]/[A]/[P] 또는 S:/O:/A:/P: 패턴 분리
function parseSoapText(text) {
  if (!text) return { cc:'', os:'', pi:'', pa:'', ps:'', A:'', P:'' };

  // 태그 추출 헬퍼 — 임의 태그 순서에 무관하게 동작
  var tag = function(t) {
    var re = new RegExp('\\[' + t + '\\]([\\s\\S]*?)(?=\\[[^\\]]+\\]|$)', 'i');
    var m = text.match(re); return m ? m[1].trim() : '';
  };

  // 패턴 1: 현재 저장 형식 [CC] [OS] [PI] [PA] [환자진술] [A] [P]
  var cc = tag('CC'), os = tag('OS'), pi = tag('PI'), pa = tag('PA');
  var ps = tag('환자진술'), a = tag('A'), p = tag('P');
  if (cc || os || pi || pa || a || p) {
    return { cc:cc, os:os, pi:pi, pa:pa, ps:ps, A:a, P:p };
  }

  // 패턴 2: 구형 [S] [O] [A] [P]
  var s2 = tag('S'), o2 = tag('O'), a2 = tag('A'), p2 = tag('P');
  if (s2 || o2 || a2 || p2) {
    return { cc:'', os:s2, pi:'', pa:o2, ps:'', A:a2, P:p2 };
  }

  // 패턴 3: S: / O: / A: / P: (줄바꿈 기반)
  var m5 = text.match(/S\s*[:\-]([\s\S]*?)(?=O\s*[:\-]|$)/i);
  var m6 = text.match(/O\s*[:\-]([\s\S]*?)(?=A\s*[:\-]|$)/i);
  var m7 = text.match(/A\s*[:\-]([\s\S]*?)(?=P\s*[:\-]|$)/i);
  var m8 = text.match(/P\s*[:\-]([\s\S]*?)$/i);
  if (m5 || m6 || m7 || m8) {
    return { cc:'', os:(m5?m5[1]:'').trim(), pi:'', pa:(m6?m6[1]:'').trim(), ps:'', A:(m7?m7[1]:'').trim(), P:(m8?m8[1]:'').trim() };
  }

  // 패턴 없으면 전체를 raw-text로 (AI 분석용)
  return { cc:'', os:'', pi:'', pa:'', ps:'', A:'', P:'', raw: true, rawText: text.trim() };
}

// 실제 불러오기 실행
function loadChartFromHanymac() {
  var sel = document.getElementById('visit-select');
  var idx = parseInt(sel ? sel.value : 0) || 0;
  var v = state.visitList[idx];
  if (!v) { showStatus('불러올 진료 기록이 없습니다.', 'err'); return; }

  var memo = v.증상 || v.내용 || v.차트내용 || v.메모 || '';
  if (!memo) { showStatus('선택한 날짜에 저장된 차트 내용이 없습니다.', 'err'); return; }

  var parsed = parseSoapText(memo);
  var date = v.진료일자 || v.일자 || '날짜미상';

  if (parsed.raw) {
    // SOAP 구조가 없는 경우 → raw-text에 넣고 탭2로
    document.getElementById('raw-text').value = parsed.rawText || memo;
    document.getElementById('inline-raw-text').value = parsed.rawText || memo;
    state.rawText = parsed.rawText || memo;
    switchTab(2);
    showStatus('📋 ' + date + ' 차트를 불러왔습니다. AI 분석을 실행하거나 직접 수정하세요.', 'ok');
  } else {
    document.getElementById('chart-cc').value = parsed.cc || '';
    document.getElementById('chart-os').value = parsed.os || '';
    document.getElementById('chart-pi').value = parsed.pi || '';
    document.getElementById('chart-pa').value = parsed.pa || '';
    document.getElementById('chart-ps').value = parsed.ps || '';
    document.getElementById('chart-a').value  = parsed.A  || '';
    document.getElementById('chart-p').value  = parsed.P  || '';
    // raw-text에도 저장 (AI 재분석 시 활용)
    document.getElementById('raw-text').value = memo;
    document.getElementById('inline-raw-text').value = memo;
    state.rawText = memo;
    // state에 analysisResult 구조 세팅 (복약지도문·문자초안 탭 활성화용)
    var ch = { cc:parsed.cc||'', os:parsed.os||'', pi:parsed.pi||'', pa:parsed.pa||'', ps:parsed.ps||'', a:parsed.A||'', p:parsed.P||'' };
    if (!state.analysisResult) {
      state.analysisResult = { chart: ch, diagnosis: { korean: [], western: [] }, smsText: '', evaluation: {} };
    } else {
      state.analysisResult.chart = ch;
    }
    switchTab(3);
    document.getElementById('tab3').classList.add('done');
    showStatus('✅ ' + date + ' 차트를 불러왔습니다. 바로 확인하거나 AI 재분석 할 수 있습니다.', 'ok');
  }
}
function initSpeech() {
  var SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (SR) {
    recState.recognition = new SR();
    recState.recognition.lang = 'ko-KR';
    recState.recognition.continuous = true;
    recState.recognition.interimResults = true;
    recState.recognition.onresult = function(e) {
      var interim = '';
      for (var i = e.resultIndex; i < e.results.length; i++) {
        if (e.results[i].isFinal) recState.fullTranscript += e.results[i][0].transcript + ' ';
        else interim += e.results[i][0].transcript;
      }
      document.getElementById('raw-text').value = recState.fullTranscript + interim;
    };
    recState.recognition.onerror = function(e) { if (e.error !== 'aborted') showStatus('음성인식 오류: ' + e.error, 'err'); };
    recState.recognition.onend = function() { if (recState.isRecording && !CFG.openAiKey) { try { recState.recognition.start(); } catch(e){} } };
  }
  updateRecModeBadge();
}

function toggleRec() { if (recState.isRecording) stopRec(); else startRec(); }

function startRec() {
  recState.fullTranscript = ''; recState.audioChunks = [];
  document.getElementById('raw-text').value = '';
  recState.elapsed = 0; recState.isRecording = true;
  recState.timer = setInterval(function() {
    recState.elapsed++;
    document.getElementById('rec-timer').textContent =
      String(Math.floor(recState.elapsed/60)).padStart(2,'0') + ':' + String(recState.elapsed%60).padStart(2,'0');
  }, 1000);
  var btn = document.getElementById('rec-btn');
  btn.textContent = '⏹️'; btn.classList.add('recording');
  var st = document.getElementById('rec-status');
  st.classList.add('active');
  if (CFG.openAiKey) {
    st.textContent = '● 녹음 중... (Whisper AI — 종료 후 자동 변환)';
    navigator.mediaDevices.getUserMedia({ audio: true }).then(function(stream) {
      var mimeType = 'audio/webm;codecs=opus';
      if (!MediaRecorder.isTypeSupported(mimeType)) mimeType = 'audio/webm';
      if (!MediaRecorder.isTypeSupported(mimeType)) mimeType = 'audio/ogg;codecs=opus';
      if (!MediaRecorder.isTypeSupported(mimeType)) mimeType = '';
      recState.mimeType = mimeType.split(';')[0];
      var options = mimeType ? { mimeType: mimeType } : {};
      recState.mediaRecorder = new MediaRecorder(stream, options);
      recState.mediaRecorder.ondataavailable = function(e) { if (e.data && e.data.size > 0) recState.audioChunks.push(e.data); };
      recState.mediaRecorder.onstop = function() { stream.getTracks().forEach(function(t){ t.stop(); }); sendToWhisper(); };
      recState.mediaRecorder.start(1000);
    }).catch(function(err) {
      showStatus('마이크 접근 오류: ' + err.message, 'err');
      recState.isRecording = false; clearInterval(recState.timer);
      btn.textContent = '🎙️'; btn.classList.remove('recording');
      st.classList.remove('active'); st.textContent = '마이크 권한을 허용해주세요.';
    });
  } else {
    st.textContent = '● 녹음 중... (다시 누르면 종료)';
    if (recState.recognition) { try { recState.recognition.start(); } catch(e){} }
  }
}

function stopRec() {
  recState.isRecording = false; clearInterval(recState.timer);
  var btn = document.getElementById('rec-btn');
  btn.textContent = '🎙️'; btn.classList.remove('recording');
  var st = document.getElementById('rec-status'); st.classList.remove('active');
  if (CFG.openAiKey && recState.mediaRecorder && recState.mediaRecorder.state !== 'inactive') {
    st.textContent = '녹음 완료. Whisper 변환 중...'; btn.disabled = true;
    recState.mediaRecorder.stop();
  } else {
    if (recState.recognition) { try { recState.recognition.stop(); } catch(e){} }
    st.textContent = '녹음 완료. AI 분석을 시작하거나 내용을 수정하세요.';
    if (recState.fullTranscript.trim()) document.getElementById('raw-text').value = recState.fullTranscript.trim();
  }
}

function sendToWhisper() {
  var progress = document.getElementById('whisper-progress');
  var btn = document.getElementById('rec-btn');
  var st = document.getElementById('rec-status');
  if (recState.audioChunks.length === 0) {
    showStatus('녹음된 오디오가 없습니다.', 'err'); btn.disabled = false;
    st.textContent = '버튼을 눌러 녹음을 시작하세요'; return;
  }
  if (progress) progress.style.display = '';
  st.textContent = 'Whisper AI 변환 중...';
  var blob = new Blob(recState.audioChunks, { type: recState.mimeType || 'audio/webm' });

  // 파일이 너무 작으면 무음/빈 녹음 — 전송하지 않음
  if (blob.size < 5000) {
    if (progress) progress.style.display = 'none';
    btn.disabled = false;
    showStatus('녹음 파일이 너무 작습니다. 마이크를 확인하거나 다시 녹음해주세요.', 'err');
    st.textContent = '녹음 실패. 마이크를 확인하고 다시 시도해주세요.'; return;
  }

  var reader = new FileReader();
  reader.onload = function() {
    var base64 = reader.result.split(',')[1];
    var hint = (CFG.whisperHint || '') + ' 맥세삭 맥침완 맥부긴 태충 신문 내관 전중 음릉천 합곡 족삼리 삼음교 백회 풍지 보중익기탕 육미지황탕 쌍화탕 소시호탕 변증 한열 음허 양허 기허 혈허 습담 간울 홧병 추나 부항 침치료';
    chrome.runtime.sendMessage({
      type: 'WHISPER_STT', apiKey: CFG.openAiKey,
      audioData: base64, mimeType: recState.mimeType || 'audio/webm', prompt: hint
    }, function(response) {
      if (progress) progress.style.display = 'none';
      btn.disabled = false;
      if (!response || !response.success) {
        showStatus('Whisper 변환 실패: ' + (response ? response.error : '응답 없음'), 'err');
        st.textContent = '변환 실패. 다시 시도하거나 직접 입력해주세요.'; return;
      }
      var text = response.text.trim();
      // Whisper 환각(hallucination) 패턴 감지 — 무음/잡음 파일일 때 발생
      var hallucinationPatterns = ['UpTitle', '자막 제작', '자막제작', 'СУБТИТРЫ', 'Subtitles by', 'MBC 뉴스', 'KBS 뉴스'];
      var isHallucination = hallucinationPatterns.some(function(p) { return text.indexOf(p) !== -1; })
                         || (text.length < 5 && recState.elapsed > 3);
      if (isHallucination) {
        showStatus('⚠️ Whisper가 음성을 인식하지 못했습니다. 마이크 입력을 확인하고 다시 녹음해주세요.', 'err');
        st.textContent = '인식 실패. 마이크를 확인하고 다시 시도해주세요.';
        document.getElementById('raw-text').value = '';
        return;
      }
      document.getElementById('raw-text').value = text;
      recState.fullTranscript = text;
      st.textContent = '✅ Whisper 변환 완료! 내용 확인 후 AI 분석을 시작하세요.';
      showStatus('✅ Whisper STT 변환 완료 (' + recState.elapsed + '초 분량)', 'ok');
    });
  };
  reader.readAsDataURL(blob);
}
function clearRaw() {
  document.getElementById('raw-text').value = '';
  recState.fullTranscript = ''; recState.audioChunks = []; recState.elapsed = 0;
  document.getElementById('rec-timer').textContent = '00:00';
  var progress = document.getElementById('whisper-progress');
  if (progress) progress.style.display = 'none';
  var st = document.getElementById('rec-status');
  st.textContent = '버튼을 눌러 녹음을 시작하세요'; st.classList.remove('active');
}

// ── TIOM ─────────────────────────────────────────────
function toggleTiom(key) {
  tiom[key] = tiom[key]==='idle' ? 'checked' : tiom[key]==='checked' ? 'unchecked' : 'idle';
  updateTiomUI();
}
function resetTiom() { tiom={T:'idle',I:'idle',O:'idle',M:'idle'}; updateTiomUI(); }
function updateTiomUI() {
  ['T','I','O','M'].forEach(function(k) {
    var el = document.getElementById('tiom-'+k); if (!el) return;
    el.className = 'tiom-item ' + tiom[k];
  });
  var unchecked = ['T','I','O','M'].filter(function(k){ return tiom[k]==='unchecked'; });
  var warn = document.getElementById('tiom-warn');
  var labels = {T:'한열(T)',I:'음식(I)',O:'대소변(O)',M:'심신(M)'};
  if (unchecked.length > 0) {
    warn.style.display = '';
    warn.textContent = '⚠ 미확인 항목: ' + unchecked.map(function(k){ return labels[k]; }).join(', ') + ' — AI 분석 시 해당 정보가 부족할 수 있습니다.';
  } else { warn.style.display = 'none'; }
}
function getTiomSummary() {
  var labels = {T:'한열',I:'음식/소화',O:'대소변',M:'수면/심신'};
  var checked=[], unchecked=[], idle=[];
  ['T','I','O','M'].forEach(function(k){
    if (tiom[k]==='checked') checked.push(labels[k]);
    else if (tiom[k]==='unchecked') unchecked.push(labels[k]);
    else idle.push(labels[k]);
  });
  var parts = [];
  if (checked.length) parts.push('확인완료: '+checked.join(', '));
  if (unchecked.length) parts.push('미확인(누락): '+unchecked.join(', '));
  if (idle.length) parts.push('미표시: '+idle.join(', '));
  return parts.join(' / ');
}

// ── 탭3: Claude AI 분석 ──────────────────────────────
// 탭2 버튼 → 탭3으로 이동 후 분석
function startAnalysis() {
  var raw = document.getElementById('raw-text').value.trim();
  var extraMemo = document.getElementById('extra-memo').value.trim();
  if (!raw && !extraMemo) { showStatus('진료 내용을 입력해주세요.', 'err'); return; }
  if (!CFG.geminiKey && !CFG.apiKey) { showStatus('설정에서 Gemini 또는 Claude API 키를 입력해주세요.', 'err'); return; }
  state.rawText = raw; state.extraMemo = extraMemo;
  switchTab(3);
  _runAnalysis(raw, extraMemo);
}

// 실제 분석 실행 (탭2/탭3 공용)
function _runAnalysis(raw, extraMemo) {
  state.rawText = raw; state.extraMemo = extraMemo;
  document.getElementById('loading3').style.display = '';

  var patientName = state.patient ? getName(state.patient) : '';
  var patientAge = state.patient ? getBirth(state.patient) : '';
  var tiomSummary = getTiomSummary();

  // 이전 진료 기록 컨텍스트
  var prevVisitContext = '';
  if (state.visitList && state.visitList.length > 1) {
    var currentVisitIdx = parseInt(document.getElementById('visit-select').value) || 0;
    var prevVisits = state.visitList.slice(currentVisitIdx + 1, currentVisitIdx + 4);
    if (prevVisits.length > 0) {
      prevVisitContext = '\n\n=== 이전 진료 기록 (경과 비교용) ===\n';
      prevVisits.forEach(function(v) {
        var date = v.진료일자||v.일자||'날짜미상';
        var memo = v.증상||v.내용||v.차트내용||v.메모||'';
        if (memo) prevVisitContext += '▶ [' + date + '] ' + memo.slice(0,300) + (memo.length>300?'...':'') + '\n';
      });
      prevVisitContext += '\n위 이전 기록을 참고하여 경과 변화(호전/악화/유지)를 evaluation.progress 항목에 반드시 분석하세요.\n';
    }
  }

  var prompt =
    '당신은 한의사를 보조하는 의료 AI입니다.\n' +
    '아래 진료 메모를 분석하여 진료 차팅을 JSON으로만 출력하세요.\n\n' +
    '=== 환자명 ===\n' + patientName + '\n\n' +
    '=== 진료 메모 (원본) ===\n' + raw + '\n' +
    (extraMemo ? '\n=== 추가 메모 ===\n' + extraMemo + '\n' : '') +
    (tiomSummary ? '\n=== TIOM 문진 ===\n' + tiomSummary + '\n' : '') +
    prevVisitContext +
    '\n=== 차팅 작성 기준 ===\n\n' +
    '【공통 원칙】\n' +
    '- 환자가 직접 말한 내용 위주로 기록. 추론·해석 최소화\n' +
    '- 성별·나이는 일절 기재하지 말 것\n' +
    '- 간결하게 작성 (불필요한 설명 생략)\n\n' +
    '[CC] 주증상:\n' +
    '- 주 호소 증상을 한 줄로 간결하게 (부위 + 증상 요약, 예: "요통·우측 어깨통증·소화불량")\n\n' +
    '[OS] 발병:\n' +
    '- 발병 시점, 원인, 계기, 발생 상황\n\n' +
    '[PI] 현병력:\n' +
    '- 증상 양상, 기간, 악화·완화 요인 상세 기술\n' +
    '- P/I: 과거력, 복용 약물 (언급된 경우만)\n' +
    '- ROS: 언급된 항목만 (한열 / 소화 / 수면 / 대소변 / 감정)\n\n' +
    '[PA] 신체평가:\n' +
    '- Pulse: 맥상(한자) - 의미 (예: 맥세삭(脈細數) - 음허화왕)\n' +
    '- Tongue: 설색/설태 (언급된 경우만)\n' +
    '- 기타 신체 소견 (언급된 경우만)\n\n' +
    '[환자진술] Patient Statement:\n' +
    '- 환자가 직접 한 인상적인 진술을 원문에 가깝게 (없으면 빈 문자열)\n\n' +
    '[A] 변증:\n' +
    '- 주변증: 한의학 변증명만 간결하게\n' +
    '- 겸증: 부수 변증 (있는 경우만)\n\n' +
    '[P] 치료계획:\n' +
    '- Tx: 침 혈자리(한자), 부항/뜸 (언급된 경우)\n' +
    '- Herb: 처방명 + 기간 (언급된 경우)\n' +
    '- Etc: 생활지도, 재진 (언급된 경우)\n\n' +
    '=== evaluation 기준 ===\n' +
    '- summary: 핵심 변증 + 주요 소견 (1~2문장)\n' +
    '- nextVisit: 다음 진료 확인 항목 (2~3가지)\n' +
    '- prognosis: 간단한 예후 안내\n' +
    (prevVisitContext ? '- progress: 이전 대비 경과 (호전/악화/유지)\n' : '') +
    '\n아래 JSON으로만 응답 (마크다운 없이 순수 JSON):\n' +
    '⚠️ JSON 문자열 값 안에 큰따옴표(")를 절대 사용하지 마세요. 인용이 필요하면 『』나 〈〉를 사용하세요.\n' +
    '{\n' +
    '  "chart": {\n' +
    '    "cc": "주증상 한 줄 요약",\n' +
    '    "os": "발병 시점·원인·계기",\n' +
    '    "pi": "현병력 상세 (양상·기간·악화완화요인·P/I·ROS)",\n' +
    '    "pa": "Pulse: 맥상(한자) - 의미\\nTongue: ...\\n기타 소견: ...",\n' +
    '    "ps": "환자가 직접 한 주요 진술 (원문 그대로, 없으면 빈 값)",\n' +
    '    "a": "주변증: ...\\n겸증: ...",\n' +
    '    "p": "Tx: 혈자리(한자)\\nHerb: 처방명 + 기간\\nEtc: ..."\n' +
    '  },\n' +
    '  "diagnosis": { "korean": ["주변증","겸증"], "western": [] },\n' +
    '  "smsText": "환자에게 보낼 문자 (150자 이내)",\n' +
    '  "evaluation": {\n' +
    '    "summary": "...", "nextVisit": "...", "prognosis": "..."' +
    (prevVisitContext ? ', "progress": "..."' : '') + '\n  }\n}';

  chrome.runtime.sendMessage({
    type: 'CLAUDE_API', apiKey: CFG.apiKey,
    payload: { model:'claude-sonnet-4-6', max_tokens:2000, messages:[{role:'user',content:prompt}] }
  }, function(response) {
    document.getElementById('loading3').style.display = 'none';
    if (chrome.runtime.lastError) { showStatus('런타임 오류: ' + chrome.runtime.lastError.message, 'err'); return; }
    if (!response || !response.success) { showStatus('AI 오류: ' + (response ? response.error : '응답 없음'), 'err'); return; }
    try {
      var text = response.data.content[0].text.trim();
      var match = text.match(/\{[\s\S]*\}/);
      if (!match) throw new Error('JSON 파싱 실패');
      var result = safeJsonParse(match[0]);
      state.analysisResult = result;
      renderAnalysis(result);
    } catch(e) { showStatus('파싱 오류: ' + e.message, 'err'); }
  });
}

function renderAnalysis(r) {
  var soap = r.soap||{}, diag = r.diagnosis||{};

  // 이전 진료 배너
  var banner = document.getElementById('prev-visit-banner');
  var detail = document.getElementById('prev-visit-detail');
  if (banner && state.visitList && state.visitList.length > 1) {
    var currentIdx = parseInt(document.getElementById('visit-select').value) || 0;
    var prevVisits = state.visitList.slice(currentIdx + 1, currentIdx + 4);
    if (prevVisits.length > 0) {
      banner.style.display = '';
      var prevHtml = prevVisits.map(function(v, i) {
        var date = v.진료일자||v.일자||'날짜미상';
        var memo = v.증상||v.내용||v.차트내용||v.메모||'(내용 없음)';
        return '<div style="margin-bottom:8px;padding-bottom:8px;border-bottom:1px solid #e0d8f0;">' +
          '<div style="font-size:11px;font-weight:700;color:#5040a8;margin-bottom:3px;">📅 ' + esc(date) + ' (' + (i===0?'직전 진료':(i+1)+'회 전') + ')</div>' +
          '<div style="font-size:12px;color:#3a3a5a;line-height:1.65;white-space:pre-wrap">' + esc(memo.slice(0,400)) + '</div></div>';
      }).join('');
      if (detail) {
        detail.innerHTML = prevHtml;
        var toggleBtn = document.getElementById('btn-toggle-prev');
        if (toggleBtn) {
          toggleBtn.onclick = function() {
            var isOpen = detail.style.display !== 'none';
            detail.style.display = isOpen ? 'none' : '';
            toggleBtn.textContent = isOpen ? '이전 기록 보기 ▼' : '이전 기록 닫기 ▲';
          };
        }
      }
    } else { banner.style.display = 'none'; }
  } else if (banner) { banner.style.display = 'none'; }

  var ch = r.chart||{};
  document.getElementById('chart-cc').value = ch.cc||'';
  document.getElementById('chart-os').value = ch.os||'';
  document.getElementById('chart-pi').value = ch.pi||'';
  document.getElementById('chart-pa').value = ch.pa||'';
  document.getElementById('chart-ps').value = ch.ps||'';
  document.getElementById('chart-a').value  = ch.a||'';
  document.getElementById('chart-p').value  = ch.p||'';
  document.getElementById('diag-ko').innerHTML = (diag.korean||[]).map(function(d){ return '<div class="diag-item">• '+esc(d)+'</div>'; }).join('') || '<div class="diag-item" style="color:var(--text3)">미확인</div>';
  document.getElementById('diag-we').innerHTML = (diag.western||[]).map(function(d){ return '<div class="diag-item">• '+esc(d)+'</div>'; }).join('') || '<div class="diag-item" style="color:var(--text3)">미확인</div>';

  var ev = r.evaluation||{};
  var evalHtml = '';
  if (typeof ev === 'string') {
    evalHtml = '<p style="white-space:pre-wrap">'+esc(ev)+'</p>';
  } else {
    var blocks = [
      {key:'summary', label:'📌 주요 소견 및 감별진단'},
      {key:'treatmentPlan', label:'📋 치료 계획 설명 평가'},
      {key:'herbAdvocacy', label:'🌿 한의학 변증 / 한약 설명 평가'},
      {key:'nextVisit', label:'🔍 다음 진료 확인사항'},
      {key:'prognosis', label:'📈 예후 및 치료 기간'}
    ];
    if (ev.progress) blocks.push({key:'progress', label:'🔄 이전 진료 대비 경과 분석', color:'#5040a8', bg:'var(--purple-bg)'});
    blocks.forEach(function(b) {
      if (!ev[b.key]) return;
      var color = b.color || 'var(--green)';
      var bg = b.bg || 'var(--green-bg)';
      evalHtml += '<div class="eval-block" style="border-left-color:'+color+';background:'+bg+'">' +
        '<div class="eval-label" style="color:'+color+'">'+b.label+'</div>' +
        '<div class="eval-body">'+esc(ev[b.key])+'</div></div>';
    });
  }
  document.getElementById('res-eval').innerHTML = evalHtml || '<p style="color:var(--text3)">평가 내용 없음</p>';

  // (no-analysis-msg removed)
  document.getElementById('tab3').classList.add('done');
}

function buildChartText() {
  var parts = [];
  var cc = document.getElementById('chart-cc').value.trim();
  var os = document.getElementById('chart-os').value.trim();
  var pi = document.getElementById('chart-pi').value.trim();
  var pa = document.getElementById('chart-pa').value.trim();
  var ps = document.getElementById('chart-ps').value.trim();
  var a  = document.getElementById('chart-a').value.trim();
  var p  = document.getElementById('chart-p').value.trim();
  if (cc) parts.push('[CC] '+cc);
  if (os) parts.push('[OS] '+os);
  if (pi) parts.push('[PI] '+pi);
  if (pa) parts.push('[PA] '+pa);
  if (ps) parts.push('[환자진술] '+ps);
  if (a)  parts.push('[A] '+a);
  if (p)  parts.push('[P] '+p);
  return parts.join('\n\n');
}

function copyClipboard() {
  var text = buildChartText();
  if (!text) { showStatus('복사할 내용이 없습니다.', 'err'); return; }
  navigator.clipboard.writeText(text).then(function(){ showStatus('✅ 차트가 클립보드에 복사됐습니다!', 'ok'); });
}

// ── 한의맥 저장 ───────────────────────────────────────
function saveToHanymac() {
  if (!state.patient) { showStatus('환자를 선택해주세요.', 'err'); return; }
  var text = buildChartText();
  if (!text) { showStatus('차트 내용이 없습니다.', 'err'); return; }
  var today = new Date().toISOString().split('T')[0];
  var chartNum = state.patient.챠트번호;
  var treatDate, treatNum;
  // 오늘 날짜 환자(대시보드 waitpat 선택)는 patient 자체의 진료정보 사용
  // 그 외(검색 또는 과거 차트 불러오기)는 visit-select 기준
  if (state.patient.진료일자 === today) {
    treatDate = today;
    treatNum = state.patient.진료번호 || 1;
  } else if (state.visitList.length > 0) {
    var idx = parseInt(document.getElementById('visit-select').value) || 0;
    var v = state.visitList[idx] || {};
    treatDate = v.진료일자 || today;
    treatNum = v.진료번호 || '';
  } else {
    treatDate = today;
    treatNum = '';
  }
  var btn = document.getElementById('btn-save-hanymac');
  btn.textContent = '저장 중...'; btn.disabled = true;
  chrome.runtime.sendMessage({
    type: 'HANYMAC_API', url: authUrl(base()+'/treat/record'),
    options: { method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ JSONdata: JSON.stringify({증상:text, 챠트번호:chartNum, 진료일자:treatDate, 진료번호:treatNum}) }) }
  }, function(response) {
    btn.textContent = '💾 한의맥 저장'; btn.disabled = false;
    if (response && response.success && response.status >= 200 && response.status < 300) {
      showStatus('✅ 한의맥에 저장되었습니다!', 'ok');
      saveToGoogleSheet();
    } else {
      showStatus('한의맥 저장 실패: ' + (response ? response.error||('HTTP '+response.status) : '응답 없음'), 'err');
    }
  });
}

// ── 공용: AI 응답 JSON 강건 파싱 ──────────────────────
// 1) 문자열 내부 제어문자 이스케이프 → 2) 파싱 실패 시 미이스케이프 따옴표 복구 후 재시도
function safeJsonParse(raw) {
  var sanitized = '', inStr = false, esc = false;
  for (var i = 0; i < raw.length; i++) {
    var ch = raw[i];
    if (esc) { sanitized += ch; esc = false; continue; }
    if (ch === '\\' && inStr) { sanitized += ch; esc = true; continue; }
    if (ch === '"') { sanitized += ch; inStr = !inStr; continue; }
    if (inStr && ch.charCodeAt(0) < 0x20) {
      if (ch === '\n') sanitized += '\\n';
      else if (ch === '\r') sanitized += '\\r';
      else if (ch === '\t') sanitized += '\\t';
    } else {
      sanitized += ch;
    }
  }
  try { return JSON.parse(sanitized); }
  catch(e) { return JSON.parse(repairInnerQuotes(sanitized)); }
}

// 문자열 값 내부의 이스케이프 안 된 큰따옴표를 \" 로 복구
// (닫는 따옴표 뒤에는 반드시 , } ] : 중 하나가 와야 한다는 JSON 규칙 이용)
function repairInnerQuotes(s) {
  var out = '', inStr = false, esc = false;
  for (var i = 0; i < s.length; i++) {
    var ch = s[i];
    if (esc) { out += ch; esc = false; continue; }
    if (ch === '\\' && inStr) { out += ch; esc = true; continue; }
    if (ch === '"') {
      if (!inStr) { inStr = true; out += ch; continue; }
      var j = i + 1;
      while (j < s.length && /\s/.test(s[j])) j++;
      if (j >= s.length || ',}]:'.indexOf(s[j]) >= 0) { inStr = false; out += ch; }
      else { out += '\\"'; }
      continue;
    }
    out += ch;
  }
  return out;
}

// ── 구글 시트 저장 ────────────────────────────────────
function saveToGoogleSheet(extraData) {
  if (!CFG.gsUrl) return;
  var r = state.analysisResult||{}, soap=r.soap||{}, diag=r.diagnosis||{};
  var g = state.guideResult||{};
  // 복약지도문: 용법 + 편지 + 주의사항
  var guideText = '';
  if (g.letter || g.dosageSummary) {
    guideText = (g.dosageSummary ? '[용법] ' + g.dosageSummary + '\n' : '') +
                (g.letter ? g.letter : '');
    if (g.cautions && g.cautions.length) {
      guideText += '\n[주의사항]\n' + g.cautions.map(function(c){ return '- ' + c; }).join('\n');
    }
  }
  var record = {
    id: state._savedRecordId || String(Date.now()),
    환자명: state.patient ? getName(state.patient) : '',
    나이성별: state.patient ? getBirth(state.patient) : '',
    진료일자: (function(){ var d=new Date(); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); })(),
    상담원문메모: state.rawText||'',                             // 구 '원본메모' → 컬럼명 일치
    주증상: document.getElementById('chart-cc').value,
    OS: document.getElementById('chart-os').value,
    PI: document.getElementById('chart-pi').value,
    PA: document.getElementById('chart-pa').value,
    환자진술: document.getElementById('chart-ps').value,
    SOAP_A: document.getElementById('chart-a').value,
    SOAP_P: document.getElementById('chart-p').value,
    한의학변증: (diag.korean||[]).join(', '),
    양방질환명: (diag.western||[]).join(', '),
    문자메시지초안: r.smsText||'',
    진료평가: (typeof r.evaluation === 'object') ? JSON.stringify(r.evaluation) : (r.evaluation||''),
    복약지도문: guideText,
    상담원문: state.rawText||''                                  // 원문 전체 (상담원문메모와 동일 내용)
  };
  if (extraData) Object.assign(record, extraData);
  chrome.runtime.sendMessage({ type:'GOOGLE_SHEET', url:CFG.gsUrl, record:record }, function(resp){
    if (resp && resp.success) {
      state._savedRecordId = record.id;
      showStatus('✅ 구글 시트 저장 완료', 'ok');
    } else {
      showStatus('⚠️ 구글 시트 저장 실패: ' + (resp ? resp.error : '응답 없음'), 'err');
    }
  });
}

