  if (!g || !pd) { showStatus('복약지도문을 먼저 생성해주세요.', 'err'); return; }
  var patientName = pd.patientName||'환자';
  var today = new Date().toISOString().split('T')[0];
  var filename = today + '_' + patientName + '_복약지도문.html';
  var html = '<!DOCTYPE html><html lang="ko"><head><meta charset="UTF-8"><title>' + patientName + ' 복약지도문</title>' +
    '<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;500;700&family=Noto+Serif+KR:wght@400;600&display=swap" rel="stylesheet">' +
    '<style>body{font-family:"Noto Serif KR","Noto Sans KR",serif;margin:0;padding:20px;background:#f5f5f5;}' +
    '.page{width:190mm;margin:0 auto;background:#fff;padding:14mm 16mm;box-sizing:border-box;box-shadow:0 2px 12px rgba(0,0,0,.1);font-size:9.5pt;line-height:1.65;}' +
    '.print-header{border-bottom:2pt solid #1a6b3a;padding-bottom:8pt;margin-bottom:10pt;display:flex;align-items:flex-end;justify-content:space-between;}' +
    '.print-clinic{font-size:13pt;font-weight:700;color:#1a6b3a;}' +
    '.print-sec{margin-bottom:8pt;}.print-sec-title{font-size:9.5pt;font-weight:700;color:#1a6b3a;border-left:2.5pt solid #1a6b3a;padding-left:5pt;margin-bottom:5pt;}' +
    '.print-list{padding-left:12pt;margin:0;}.print-list li{margin-bottom:3pt;font-size:9pt;}' +
    '.print-footer{margin-top:8pt;padding-top:5pt;border-top:.5pt solid #c8c2b8;font-size:7.5pt;color:#a09890;text-align:center;}' +
    '@media print{body{background:#fff;padding:0;}.page{box-shadow:none;width:100%;padding:10mm 14mm;}}</style></head><body>' +
    '<div class="page">' + buildGuideHtml(g, patientName, pd) + '</div></body></html>';
  var blob = new Blob([html], { type:'text/html;charset=utf-8' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a'); a.href=url; a.download=filename;
  document.body.appendChild(a); a.click();
