function initSmsTab() {
  if (state.patient) {
    var name = getName(state.patient);
    var phone = getPhone(state.patient);
    document.getElementById('sms-pt-name').textContent = name;
    document.getElementById('sms-pt-phone').textContent = phone ? '📞 ' + phone : '(전화번호 없음)';
    document.getElementById('sms-patient-info').style.display = '';
    // 전화번호 표시
    var phoneRow = document.getElementById('sms-phone-row');
    var phoneDisplay = document.getElementById('sms-phone-display');
    if (phone && phoneRow && phoneDisplay) {
      phoneDisplay.textContent = phone;
      phoneRow.style.display = 'flex';
    } else if (phoneRow) {
      phoneRow.style.display = 'none';
    }
  }
  // AI가 만든 문자 초안이 있으면 자동 채우기
  if (state.analysisResult && state.analysisResult.smsText) {
    var existing = document.getElementById('sms-message').value;
    if (!existing) {
      document.getElementById('sms-message').value = state.analysisResult.smsText;
      document.getElementById('result5').style.display = '';
    }
  }
  // 자보 자동 감지
  var r = state.analysisResult||{}, ch2=r.chart||{};
  var isAuto = /자보|교통사고|자동차/.test((ch2.cc||'')+(ch2.os||'')+(ch2.pi||'')+(ch2.a||'')+(ch2.p||''));
  document.getElementById('chk-auto-insurance').checked = isAuto;
  if (isAuto) showStatus('🚗 자동차보험 환자로 감지됐습니다.', 'ok');
}

