function generateSmsMsg() {
  if (!CFG.geminiKey && !CFG.apiKey) { showStatus('설정에서 Gemini 또는 Claude API 키를 입력해주세요.', 'err'); return; }
  var msgType = document.querySelector('input[name="msg-type"]:checked').value;
  var nextVisit = document.getElementById('kk-next-visit').value.trim();
  var treatCount = document.getElementById('kk-treat-count').value.trim();
  var extra = document.getElementById('kk-extra').value.trim();
  var sig = CFG.kakaoSig || '경희늘푸른한의원';
  var patientName = state.patient ? getName(state.patient) : '환자';
  var r = state.analysisResult||{}, ch3=r.chart||{}, diag=r.diagnosis||{};
  var isAuto = document.getElementById('chk-auto-insurance').checked;

  document.getElementById('loading5').style.display = '';
  document.getElementById('result5').style.display = 'none';
  document.getElementById('btn-gen-sms').disabled = true;

  var typeDesc = { lifestyle:'생활습관 지도 위주', nextvisit:'다음 내원 안내 위주', combined:'생활습관 지도 + 다음 내원 안내 통합', followup:'치료 경과 확인 + 다음 내원 안내' }[msgType]||'통합';
  var autoNote = isAuto ? '\n\n【자동차보험 환자 필수 문구】\n- 초기 2주간: 매일 내원 집중 치료\n- 이후 약 2개월간: 주 3회 꾸준히 내원\n- 이 치료 일정이 교통사고 후유증 완전 회복의 핵심임을 강조' : '';

  var prompt =
    '당신은 경희늘푸른한의원의 환자 문자 메시지 작성 전문가입니다.\n' +
    '아래 예시들의 문체와 구조를 완벽하게 학습하여, 동일한 스타일로 새 메시지를 작성하세요.\n\n' +
    '=== 문체 학습 예시 ===\n\n' +
    '[경희늘푸른한의원 진료 안내] 김유신 님, 오늘 진료받으시느라 고생 많으셨습니다. ' +
    '지난주 자동차 사고 이후 제때 치료를 받지 못하셔서 목과 허리의 어혈이 굳고 근육이 많이 긴장된 상태입니다. ' +
    '무거운 물건을 들거나 무리한 운동은 피해주시고, 따뜻한 물로 샤워하시면서 안정을 취해주세요. ' +
    '당분간 2주에서 한 달 정도는 주 3회 집중적으로 내원하셔서 치료를 받으셔야 합니다. ' +
    '바쁘시더라도 빠른 회복을 위해 내일 꼭 다시 내원해 주세요!\n\n' +
    '=== 문체 핵심 규칙 ===\n' +
    '1. 시작: "[경희늘푸른한의원 진료 안내] 환자명 님, 오늘 ~하시느라 고생 많으셨습니다."\n' +
    '2. 현재 상태: 한의학 용어를 쉬운 말로 풀어 설명\n' +
    '3. 생활습관: 구체적이고 실천 가능한 조언 1~2가지\n' +
    '4. 내원 안내: "~주간 주 3회 → 이후 2주에 1회" 패턴\n' +
    '5. 마무리: "내일/모레/~일 꼭 다시 내원해 주세요!" 처럼 구체적 행동 촉구\n' +
    '6. 전체 길이: 300~450자\n' +
    '7. 이모지 사용 금지\n' +
    '8. 서명 불필요 (헤더에 포함됨)\n' +
    autoNote +
    '\n\n=== 새 메시지 작성 정보 ===\n' +
    '환자명: ' + patientName + '\n메시지 유형: ' + typeDesc + '\n' +
    '주증상 (CC): ' + (ch3.cc||'미입력') + '\n' +
    '현병력 (PI): ' + (ch3.pi||'미입력') + '\n' +
    '변증 (A): ' + (ch3.a||'미입력') + '\n' +
    '치료계획 (P): ' + (ch3.p||'미입력') + '\n' +
    '한의학 변증: ' + (diag.korean||[]).join(', ') + '\n' +
    (nextVisit ? '다음 내원 일정: ' + nextVisit + '\n' : '') +
    (treatCount ? '권장 치료 횟수: ' + treatCount + '\n' : '') +
    (extra ? '추가 강조 사항: ' + extra + '\n' : '') +
    '\n아래 JSON 형식으로만 응답하세요:\n{"message": "완성된 문자 메시지 전문"}';

  chrome.runtime.sendMessage({
    type: 'CLAUDE_API', apiKey: CFG.apiKey,
    payload: { model:'claude-sonnet-4-6', max_tokens:1000, messages:[{role:'user',content:prompt}] }
  }, function(response) {
    document.getElementById('loading5').style.display = 'none';
    document.getElementById('btn-gen-sms').disabled = false;
    if (!response || !response.success) { showStatus('메시지 생성 오류: ' + (response ? response.error : '응답 없음'), 'err'); return; }
    try {
      var text = response.data.content[0].text.trim();
      var match = text.match(/\{[\s\S]*\}/);
      if (!match) throw new Error('JSON 파싱 실패');
      var result = safeJsonParse(match[0]);
      document.getElementById('sms-message').value = result.message||'';
      document.getElementById('result5').style.display = '';
      document.getElementById('tab5').classList.add('done');
    } catch(e) { showStatus('파싱 오류: ' + e.message, 'err'); }
  });
}

