// ── 탭3 인라인 입력 동기화 ──────────────────────────
function syncInlineInput() {
  // 탭2의 진료 메모 → 탭3 입력란에 자동 반영
  var rawEl = document.getElementById('raw-text');
  var inlineEl = document.getElementById('inline-raw-text');
  var extraEl = document.getElementById('extra-memo');
  var inlineExtraEl = document.getElementById('inline-extra-memo');
  if (rawEl && inlineEl && !inlineEl.value) {
    inlineEl.value = rawEl.value;
  }
  if (extraEl && inlineExtraEl && !inlineExtraEl.value) {
    inlineExtraEl.value = extraEl.value;
  }
}

function toggleInlineInput() {
  var area = document.getElementById('inline-input-area');
  var btn = document.getElementById('btn-toggle-inline-input');
  if (!area || !btn) return;
  var isOpen = area.style.display !== 'none';
  area.style.display = isOpen ? 'none' : '';
  btn.textContent = isOpen ? '입력 내용 보기 ▼' : '입력 내용 닫기 ▲';
  if (!isOpen) syncInlineInput(); // 열 때 동기화
}

// 탭3에서 직접 AI 분석 실행
function startAnalysisInline() {
  var inlineRaw = document.getElementById('inline-raw-text').value.trim();
  var inlineExtra = document.getElementById('inline-extra-memo').value.trim();
  // 탭2 입력값도 fallback으로 사용
  var raw = inlineRaw || document.getElementById('raw-text').value.trim();
  var extra = inlineExtra || document.getElementById('extra-memo').value.trim();
  if (!raw && !extra) {
    // 입력창이 닫혀있으면 열어주기
    var area = document.getElementById('inline-input-area');
    if (area && area.style.display === 'none') {
      toggleInlineInput();
      showStatus('진료 내용을 입력해주세요.', 'err');
    } else {
      showStatus('진료 내용을 입력해주세요.', 'err');
    }
    return;
  }
  if (!CFG.geminiKey && !CFG.apiKey) { showStatus('설정에서 Gemini 또는 Claude API 키를 입력해주세요.', 'err'); return; }
  // 탭2 필드도 동기화
  if (raw) document.getElementById('raw-text').value = raw;
  if (extra) document.getElementById('extra-memo').value = extra;
  state.rawText = raw;
  state.extraMemo = extra;
  // startAnalysis 호출 (탭 이동 없이 현재 탭3에서 실행)
  _runAnalysis(raw, extra);
}

// ── 클립보드 공통 ────────────────────────────────────
function copyToClipboard(txt, onSuccess) {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(txt).then(onSuccess).catch(function(){ fallbackCopy(txt, onSuccess); });
  } else { fallbackCopy(txt, onSuccess); }
}
function fallbackCopy(txt, onSuccess) {
  var ta = document.createElement('textarea');
  ta.value = txt; ta.style.position='fixed'; ta.style.opacity='0';
  document.body.appendChild(ta); ta.focus(); ta.select();
  try { document.execCommand('copy'); if (onSuccess) onSuccess(); }
  catch(e) { showStatus('복사 실패: ' + e.message, 'err'); }
  document.body.removeChild(ta);
}


